import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(15))
G.add_edges_from([(2,14), (6,13), (7,13), (10,13), (6,14)])
for u in range(15):
    for v in range(u+1, 15):
        if (u, v) not in G.edges and (v, u) not in G.edges:
            G.add_edge(u, v)
            if len(list(nx.find_cycle(G))) > 0:
                G.remove_edge(u, v)
print(G.edges)
